namespace SanSo.Api;
public sealed class SafeProblemMiddleware(RequestDelegate next,ILogger<SafeProblemMiddleware> log)
{
 public async Task Invoke(HttpContext context){try{context.Response.Headers["X-Content-Type-Options"]="nosniff";context.Response.Headers["X-Frame-Options"]="DENY";context.Response.Headers["Referrer-Policy"]="no-referrer";context.Response.Headers["Content-Security-Policy"]="default-src 'none'; frame-ancestors 'none'";await next(context);}catch<UnauthorizedAccessException>{await Problem(context,401,"Unauthorized","Authentication or tenant membership is invalid.");}catch<ForbiddenException>{await Problem(context,403,"Forbidden","You do not have permission for this action.");}catch<ArgumentException e>{await Problem(context,400,"Invalid request",e.Message);}catch<InvalidOperationException e>{await Problem(context,409,"Conflict",e.Message);}catch(Exception e){var correlation=context.TraceIdentifier;log.LogError(e,"Unhandled request failure {CorrelationId}",correlation);await Problem(context,500,"Unexpected error",$"Request failed. Correlation: {correlation}");}}
 private static async Task Problem(HttpContext c,int status,string title,string detail){c.Response.StatusCode=status;c.Response.ContentType="application/problem+json";await c.Response.WriteAsJsonAsync(new{type=$"https://sanso.invalid/problems/{status}",title,status,detail,instance=c.Request.Path,correlationId=c.TraceIdentifier});}
}
